SCHEMA = "{\n  \"protocol\": {\"title\": string, \"number\": string|null, \"sponsor\": string|null, \"phase\": string|null, \"indication\": string|null, \"version\": string|null, \"design\": string /* 2-3 sentences */},\n  \"arms\": [{\"id\": \"A\", \"name\": string, \"description\": string}],\n  \"anchors\": [{\"id\": \"screening\", \"label\": string, \"kind\": \"start\"|\"relative\"|\"ask\", \"relative_to\": anchorId|null, \"offset_days\": number|null,\n     \"is_day1\": boolean /* the anchor study days are numbered from */, \"day_zero\": boolean /* true if the protocol calls that anchor Day 0 */,\n     \"set_by_visit\": visitId|null /* the visit whose ACTUAL date fixes this anchor, e.g. Day 1 = actual C1D1 */,\n     \"question\": string|null /* \"ask\": short question for the site */, \"optional\": boolean,\n     \"estimates\": [{\"when\": [{\"question\": questionId, \"in\": [value]}], \"relative_to\": anchorId, \"offset_days\": number}] /* \"ask\": planned timing, used only to order visits */,\n     \"note\": string|null}],\n  \"questions\": [{\"id\": \"arm\", \"label\": string /* 1-3 words */, \"text\": string /* max 60 characters, plain words */, \"scope\": \"participant\"|\"study\"|\"decision\",\n     \"ask_at\": null | {\"visit\": visitId, \"n\": number|null} | {\"anchor\": anchorId} /* decision only: when the answer becomes known */,\n     \"kind\": \"choice\"|\"boolean\"|\"number\", \"options\": [{\"value\": string, \"label\": string /* short */}], \"help\": string /* max 90 characters */, \"default\": string|number|null}],\n  \"visits\": [visit],\n  \"events\": [{\"id\": string, \"label\": string, \"repeatable\": boolean,\n     \"questions\": [{\"id\": string, \"label\": string, \"text\": string /* max 60 characters */, \"kind\": \"choice\"|\"boolean\", \"options\": [{\"value\": string, \"label\": string}]}] /* asked when the event is logged; the event date is always asked */,\n     \"visits\": [visit] /* anchor ignored: offset_days counts from the event date; include_if may use the event's questions */,\n     \"ends_schedule\": boolean /* early termination, withdrawal: cancels every later scheduled visit */,\n     \"sets_anchor\": anchorId|null /* e.g. a progression event sets the progression anchor */,\n     \"note\": string|null /* combine rules etc. */}],\n  \"rules\": [{\"id\": string, \"label\": string /* max 40 characters: the thing that happens, \"Injection 2 given\" */,\n     \"when\": {\"anchor\": anchorId} | {\"event\": eventId} /* its date: an anchor's date (entered, or set by its visit's actual date) or the logged event's date */,\n     \"stop_visits\": [visitId] /* scheduled visits (every occurrence) still to come after that date that no longer happen */,\n     \"stop_all\": boolean /* participation ends: every later visit stops, except visits counted from the anchor this event sets */,\n     \"same_day\": \"keep\"|\"cancel\" /* a stopped visit falling on the trigger date: still done (\"keep\") or not */,\n     \"starts\": anchorId|null /* the new part of the schedule it opens, if any */,\n     \"blocks\": [ruleId] /* rules that may no longer happen once this one has (an AESI rules out Injection 2) */,\n     \"allowed\": null | {\"relative_to\": anchorId, \"min_days\": number|null, \"max_days\": number|null /* inclusive, in days after relative_to */, \"not_on_visit\": visitId|null} /* when the trigger itself may happen */,\n     \"effect\": string /* max 160 characters, plain words: what changes for the participant */,\n     \"source\": string|null /* \"Section 3.6.2.1.8, p. 74; SoA footnote 13\" */}],\n  \"review_questions\": [{\"id\": string, \"text\": string /* max 110 characters */, \"why\": string /* what the protocol says, with page */, \"recommended\": value,\n     \"options\": [{\"value\": string, \"label\": string, \"patches\": [{\"target\": \"visit\"|\"anchor\", \"id\": string, \"field\": \"offset_days\"|\"window_before\"|\"window_after\"|\"duration_days\"|\"repeat.count\"|\"repeat.every_days\"|\"repeat.chain\"|\"repeat.open_ended\"|\"repeat.until_anchor\", \"value\": any}]}]}],\n  \"notes\": [string]\n}\nwhere visit = {\n    \"id\": string, \"code\": string /* \"SCR\", \"C1D1\" */, \"name\": string, \"phase\": \"Screening\"|\"Run-in\"|\"Treatment\"|\"Period 1\"|\"Washout\"|\"Surgery\"|\"Follow-up\"|\"Extension\"|other short label,\n    \"modality\": \"site\"|\"phone\"|\"home\"|\"remote\",\n    \"anchor\": anchorId, \"offset_days\": number, \"window_before\": number, \"window_after\": number,\n    \"follows\": visitId|null /* place relative to the SAME occurrence of another visit instead of the anchor (C1D8 follows C1D1, offset 7), so delays carry over */,\n    \"follows_occurrence\": \"same\"|\"last\" /* \"last\": after the LAST occurrence of a repeating visit, e.g. safety follow-up 30 days after the last dose */,\n    \"duration_days\": number|null /* confinement, in-house stay, e-diary or reactogenicity diary period */,\n    \"include_if\": [{\"question\": questionId, \"in\": [value]}] /* all must hold; [] = always */,\n    \"repeat\": null | {\"every_days\": number, \"count\": number|null, \"count_question\": questionId|null, \"start_n\": number, \"label_pattern\": \"Cycle {n} Day 1\", \"code_pattern\": \"C{n}D1\",\n       \"chain\": boolean /* next occurrence counts from the previous one's ACTUAL date (treatment cycles) */,\n       \"open_ended\": boolean /* continues until until_anchor (progression etc.); count = how many to show ahead */,\n       \"until_anchor\": anchorId|null /* no occurrence after this anchor's date */,\n       \"overrides\": [{\"n\": [number], \"add\": [procedure], \"remove\": [procedure name], \"note\": string|null}]},\n    \"procedures\": [procedure] /* EVERY assessment the schedule table marks for this visit, nothing else */,\n    \"timepoints\": [{\"label\": \"2 h post-dose\", \"offset_min\": 120, \"window_before_min\": 10, \"window_after_min\": 10, \"procedures\": [procedure]}] /* intra-day samples relative to dose time; pre-dose = offset_min 0 with window_before_min */,\n    \"condition\": string|null /* max 150 characters, this visit only */,\n    \"source\": string|null /* \"Table 3, p. 41\" */\n  }\nand procedure = string | {\"name\": string, \"if\": [{\"question\": questionId, \"in\": [value]}]}"
RULES = "Rules:\n- Exactly one anchor has kind \"start\": the first date a site knows for a new participant (usually screening). Computable anchors are \"relative\". If screening is a range, make Day 1 relative with a typical offset, set_by_visit = the Day 1 visit, and add a review_question about the offset.\n- offset_days counts calendar days from the anchor (anchor = 0). With no Day 0, \"Day 8\" from Day 1 is offset 7. Weeks = 7 days, months = 30 days unless defined. \"±3 days\" → window_before 3, window_after 3. Protocols that number Day 0 (cell/gene therapy infusion, vaccination, device implant): that anchor has day_zero true; lymphodepletion etc. are negative offsets.\n- Questions: \"participant\" = differs per participant and is known at enrollment (arm, cohort, part, dose level, crossover sequence, childbearing potential, age group, optional sub-study consent). \"study\" = same for every participant at a site (site country for country-limited procedures, which part the site runs). \"decision\" = only known later, with ask_at: run-in or lead-in success, eligibility re-check before dosing, responder status in randomized withdrawal, re-randomization, sub-study assignment after screening results, entering an extension, continuing after a response assessment. Gate later visits with include_if on the decision. Keep every text short and plain.\n- Arms/cohorts/parts/sub-studies/sequences: a participant choice question + include_if. Basket/umbrella/platform: sub-study assignment is a decision (after screening) unless known at enrollment.\n- Crossover: one anchor per period start, relative to the previous period's start (period length + washout), set_by_visit = that period's first visit. Sequence question; visit names may differ by sequence via include_if.\n- Treatment cycles: Day 1 of the first cycle anchors on Day 1; days within a cycle use \"follows\" the cycle's Day 1 visit (same occurrence n). Later cycles: repeat with chain true. Cycles of different lengths: separate visit definitions (C1 vs C2+), the later one follows the earlier with the first cycle's length. \"Until progression / unacceptable toxicity\": open_ended true, until_anchor = a \"progression\" ask anchor, count = how many to show ahead (default 6), and a review_question about the count.\n- Assessments on a fixed calendar grid (imaging every 8 weeks from Day 1 regardless of delays): anchor-based repeat with chain false.\n- Events: every event the protocol says triggers visits or ends participation: disease progression (sets_anchor), early discontinuation/withdrawal (ends_schedule true, add its end-of-treatment and follow-up visits), unscheduled visit, self-administration/rescue use/exacerbation/relapse/flare, adverse event of special interest, pregnancy. Each with its required visits and windows. Put combine rules in note.\n- rules: what happens to the schedule IF something happens. Read the whole protocol (design, synopsis, visit descriptions, schedule-table footnotes, discontinuation and stopping sections) and write one rule for EVERY statement that visits stop, are replaced, end, or that one thing rules out another: \"participants who receive X transition to ... and do not complete further ... visits\", \"unless they have received ...\", \"after progression, follow-up continues\", \"withdrawal ends participation\", \"an AESI precludes Injection 2\". Typical rules:\n  · a later period, open-label extension, rescue or re-treatment that replaces the rest of the current period: when = the anchor of the new period's first dose/visit, stop_visits = every later visit of the current period INCLUDING its end-of-study visit, starts = that anchor, same_day per the protocol;\n  · progression or end of treatment: stop_visits = the remaining treatment visits, never stop_all when follow-up continues;\n  · withdrawal, death, or pregnancy that ends participation: stop_all (the event also has ends_schedule true);\n  · treatment stops but visits continue: a rule with no stops whose effect says so;\n  · one thing ruling out another: blocks; limits on when the trigger may happen (\"more than 4 and up to 20 weeks after Injection 1\", \"not on the Week 4 visit day\"): allowed.\n  The DATE drives a replacement: visits a rule stops need no include_if on whether the trigger will happen. When the trigger can happen at any time within a range rather than at one fixed visit, do not add a decision asking in advance whether it will; a choice made at one fixed visit (entering an extension at the last visit) stays a decision. A visit that starts only after the trigger is anchored on the trigger's anchor. Every rule cites its source.\n- Telephone, home or remote visits: modality. Serial PK/PD/ECG/spirometry sampling: timepoints on the visit. Confinement or diary periods: duration_days. Long-term follow-up: repeat (every_days 365 etc.).\n- Repeats that run until the final visit or end of study: until_anchor on an \"ask\" end-of-study anchor.\n- Procedures come from the schedule table column for that visit; never list a row left blank for that column. A footnote limiting a row to some participants or sites → {\"name\",\"if\"}. Assessments only at some occurrences of a repeat → repeat.overrides.\n- review_questions: up to 6, only where the protocol leaves a real choice or is ambiguous (ranges, \"at least\", conflicting table and text, open-ended counts). Each option carries the patches that apply it; recommended = the best reading. Never ask what the protocol states.\n- condition: short and visit-specific; study-wide rules go once in notes. Page text for schedule tables keeps column positions: an \"X\" belongs to the column it sits under.\n- Use only the protocol. Record any other assumption in notes."
